-- Do not backfill: legacy provider requests did not carry an attempt token.
ALTER TABLE billing_invoices ADD COLUMN checkout_attempt_token uuid;
CREATE UNIQUE INDEX billing_checkout_attempt_token ON billing_invoices(checkout_attempt_token) WHERE checkout_attempt_token IS NOT NULL;
ALTER TABLE admin_audit_events DROP CONSTRAINT admin_audit_events_action_check;
ALTER TABLE admin_audit_events ADD CONSTRAINT admin_audit_events_action_check CHECK (action IN ('owner.bootstrapped', 'owner.transferred_out', 'owner.transferred_in', 'invitation.created', 'invitation.email_accepted', 'invitation.email_failed', 'invitation.cancelled', 'invitation.accepted', 'member.permissions_changed', 'member.removed', 'business.updated', 'contact.created', 'contact.imported', 'contact.updated', 'file.created', 'file.restored', 'file.deleted', 'resource.created', 'booking.created', 'booking.cancelled', 'invoice.created', 'invoice.issued', 'invoice.voided', 'invoice.payment_recorded', 'invoice.checkout_started', 'invoice.checkout_created', 'invoice.payment_confirmed', 'payment_review.acknowledged', 'invoice.checkout_recovered', 'invoice.checkout_linked'));
